      pendingNextEventCredit: int("pendingNextEventCredit").default(0).notNull(),
      pendingCreditRedeemedEventId: int("pendingCreditRedeemedEventId"),
      // Orden $0 (paymentStatus='approved') donde viven los orderItems/tickets
