      enrollCodeExpiresAt: timestamp("enrollCodeExpiresAt"),
      deviceTokenHash: varchar("deviceTokenHash", { length: 255 }),
      enrolled: int("enrolled").default(0).notNull(),
      active: int("active").default(1).notNull(),
