async function deleteOrderCascade(orderId) {
  const db = await getDb();
  if (!db) throw new Error("Database not available");
  const [order] = await db.select().from(orders).where(eq8(orders.id, orderId)).limit(1);
  if (!order) return { success: true };
  const ledgerEntries = await db.select().from(playcoinsLedger).where(eq8(playcoinsLedger.orderId, orderId));
  const prepaidEntries = await db.select().from(prepaidLedger).where(eq8(prepaidLedger.orderId, orderId));
  const effects = computeOrderDeleteEffects(order, ledgerEntries, prepaidEntries);
  if (effects.decrementSoldCount) {
    const items = await db.select().from(orderItems).where(eq8(orderItems.orderId, orderId));
    for (const item of items) {
      await db.update(ticketTypes).set({ soldCount: sql4`GREATEST(soldCount - ${item.quantity}, 0)` }).where(eq8(ticketTypes.id, item.ticketTypeId));
    }
  }
  for (const reversal of effects.playcoinsReversals) {
    await adjustPlaycoinsManually(reversal.customerId, reversal.delta, `Orden #${order.orderNumber} eliminada`);
  }
  for (const reversal of effects.prepaidReversals) {
    await reversePrepaidForDeletedOrder(reversal.customerId, reversal.delta, order.id, order.orderNumber);
  }
  if (effects.decrementCustomerTotals) {
    const email = order.buyerEmail.trim().toLowerCase();
    const [customer] = await db.select().from(customers).where(eq8(customers.email, email)).limit(1);
    if (customer) {
      await db.update(customers).set({
        totalOrders: Math.max(0, customer.totalOrders - 1),
        totalSpent: String(Math.max(0, Number(customer.totalSpent) - Number(order.total)))
      }).where(eq8(customers.id, customer.id));
    }
  }
  await db.delete(orderItems).where(eq8(orderItems.orderId, orderId));
  await db.delete(tickets).where(eq8(tickets.orderId, orderId));
  await db.delete(referrals).where(eq8(referrals.orderId, orderId));
  await db.delete(ambassadorCommissions).where(eq8(ambassadorCommissions.orderId, orderId));
  await db.delete(ambassadorClients).where(eq8(ambassadorClients.firstOrderId, orderId));
  await db.delete(orders).where(eq8(orders.id, orderId));
  return { success: true };
}
