var INK2 = "#1a1a1a";
var MUTED2 = "#666666";
var BORDER2 = "#dddddd";
var GREEN = "#1f9d55";
var RED = "#d9538f";
function drawTable(doc, columns, rows, startY) {
  const x = doc.page.margins.left;
  let y = startY;
  const totalWidth = columns.reduce((a, c) => a + c.width, 0);
  const drawHeader = () => {
    doc.fontSize(10).fillColor(INK2);
    columns.forEach((c, i) => {
      doc.text(c.label, x + columns.slice(0, i).reduce((a, cc) => a + cc.width, 0), y, { width: c.width });
    });
    y += 16;
    doc.moveTo(x, y).lineTo(x + totalWidth, y).strokeColor(BORDER2).stroke();
    y += 6;
  };
  drawHeader();
  for (const row of rows) {
    if (y > doc.page.height - doc.page.margins.bottom - 20) {
      doc.addPage();
      y = doc.page.margins.top;
      drawHeader();
    }
    doc.fontSize(10);
    row.forEach((cell, i) => {
      const text4 = typeof cell === "string" ? cell : cell.text;
      const color = typeof cell === "string" ? INK2 : cell.color ?? INK2;
      doc.fillColor(color).text(text4, x + columns.slice(0, i).reduce((a, cc) => a + cc.width, 0), y, { width: columns[i].width });
    });
    y += 18;
  }
  return y;
}
function drawBarChart(doc, series, rows, x, y, width, height) {
  const maxValue = Math.max(1, ...rows.flatMap((r) => r.values));
  const groupWidth = width / rows.length;
  const barWidth = Math.min(36, groupWidth / (series.length + 1));
  const gap = 6;
  rows.forEach((row, i) => {
    const groupX = x + i * groupWidth + (groupWidth - barWidth * series.length - gap * (series.length - 1)) / 2;
    row.values.forEach((value, s2) => {
      const h = value / maxValue * height;
      doc.rect(groupX + s2 * (barWidth + gap), y + height - h, barWidth, h).fill(series[s2].color);
    });
    doc.fontSize(8).fillColor(MUTED2).text(row.label, x + i * groupWidth, y + height + 6, { width: groupWidth, align: "center" });
  });
  const legendY = y + height + 22;
  let legendX = x;
  series.forEach((s2) => {
    doc.fontSize(8).fillColor(s2.color).text("\u25A0 ", legendX, legendY, { continued: true }).fillColor(MUTED2).text(`${s2.name}   `, { continued: true });
    legendX += 14 + s2.name.length * 4.2 + 24;
  });
  doc.text("", { continued: false });
  return legendY + 14;
}

