// shared/eventBudget.ts
init_expenses();
function extraIncomeTotalFor(lines) {
  return (lines ?? []).reduce((sum2, l) => sum2 + (l.unitPrice || 0) * (l.quantity || 0), 0);
}
function extraVenueCostFor(lines) {
  return (lines ?? []).reduce((sum2, l) => sum2 + (l.venueCostPerUnit || 0) * (l.quantity || 0), 0);
}
function expenseLineAmounts(line2) {
  if (line2.ivaMode === "mas_iva") {
    const iva = Math.round(line2.amount * 0.19);
    return { total: line2.amount + iva, net: line2.amount, iva };
  }
  return { total: line2.amount, net: line2.amount, iva: 0 };
}
function toPnlExpense2(line2) {
  if (line2.ivaMode === "mas_iva") {
    const { total, net, iva } = expenseLineAmounts(line2);
    return { amountTotal: total, netAmount: net, ivaAmount: iva, documentType: "factura", category: line2.category };
  }
  return {
    amountTotal: line2.amount,
    netAmount: line2.amount,
    ivaAmount: 0,
    documentType: "sin_documento",
    category: line2.category
  };
}
function attendanceForTiers(tiers) {
  return tiers.reduce((sum2, t2) => sum2 + t2.expectedQty * (t2.personasPorEntrada || 1), 0);
}
function ticketsSoldForTiers(tiers) {
  return tiers.reduce((sum2, t2) => sum2 + t2.expectedQty, 0);
}
function ticketRevenueForTiers(tiers) {
  return tiers.reduce((sum2, t2) => sum2 + t2.price * t2.expectedQty, 0);
}
function computeBreakeven(params) {
  const {
    avgPrice,
    avgPersonasPorEntrada,
    otherRevenuePerPerson,
    venueBarSharePercent,
    variableCostPerPerson,
    commissionPercent,
    cardFeePercent,
    ivaApplies,
    extraNetContribution,
    onlineSalesNoIva
  } = params;
  const fixedExpensesTotal = Math.max(0, params.fixedExpensesTotal - extraNetContribution);
  if (avgPrice <= 0) return null;
  const venueShareCostPerTicket = otherRevenuePerPerson * avgPersonasPorEntrada * venueBarSharePercent / 100;
  const variableCostPerTicket = variableCostPerPerson * avgPersonasPorEntrada + venueShareCostPerTicket;
  const k = ivaApplies ? 100 / 119 : 1;
  const kTicket = onlineSalesNoIva ? 1 : k;
  const barPerTicket = otherRevenuePerPerson * avgPersonasPorEntrada;
  const rate = (commissionPercent + cardFeePercent) / 100;
  const contributionMargin = avgPrice * (kTicket - rate) + barPerTicket * (k - rate) - variableCostPerTicket;
  if (contributionMargin <= 0) return null;
  return Math.ceil(fixedExpensesTotal / contributionMargin);
}
function computeBudgetResult(input) {
  const attendance = attendanceForTiers(input.revenueTiers);
  const ticketsSold = ticketsSoldForTiers(input.revenueTiers);
  const ticketRevenue = ticketRevenueForTiers(input.revenueTiers);
  const otherRevenue = Math.round(input.otherRevenuePerPerson * attendance);
  const extraIncomeTotal = Math.round(extraIncomeTotalFor(input.extraIncomes));
  const extraVenueCost = Math.round(extraVenueCostFor(input.extraIncomes));
  const entriesAndBarIncome = ticketRevenue + otherRevenue;
  const grossIncome = entriesAndBarIncome + extraIncomeTotal;
  const variableCostTotal = Math.round(input.variableCostPerPerson * attendance);
  const venueBarSharePercent = Math.min(100, Math.max(0, input.venueBarSharePercent ?? 0));
  const venueBarShare = Math.round(otherRevenue * venueBarSharePercent / 100);
  const ambassadorCommissions2 = Math.round(entriesAndBarIncome * input.commissionPercent / 100);
  const directExpenses = input.expenseLines.map(toPnlExpense2);
  const onlineSalesNoIva = !!input.ivaApplies && !!input.onlineSalesNoIva;
  const ivaExemptIncome = onlineSalesNoIva ? ticketRevenue + extraIncomeTotal : 0;
  const pnl = computePnl({
    ivaApplies: input.ivaApplies,
    ivaExemptIncome,
    grossIncome,
    cogs: variableCostTotal,
    ambassadorCommissions: ambassadorCommissions2,
    cardFeeBase: grossIncome,
    cardFeePercent: input.cardFeePercent,
    directExpenses,
    generalExpenses: [],
    prorationWeight: 1,
    extraCostsTotal: venueBarShare + extraVenueCost
  });
  const pnlWithoutFixed = computePnl({
    ivaApplies: input.ivaApplies,
    ivaExemptIncome,
    grossIncome,
    cogs: variableCostTotal,
    ambassadorCommissions: ambassadorCommissions2,
    cardFeeBase: grossIncome,
    cardFeePercent: input.cardFeePercent,
    directExpenses: [],
    generalExpenses: [],
    prorationWeight: 1,
    extraCostsTotal: venueBarShare + extraVenueCost
  });
  const maxDirectExpenses = Math.round(
    pnlWithoutFixed.netProfit - pnlWithoutFixed.netIncome * input.marginTargetPercent / 100
  );
  const avgTicketPrice = ticketsSold > 0 ? ticketRevenue / ticketsSold : null;
  const avgPersonasPorEntrada = ticketsSold > 0 ? attendance / ticketsSold : 1;
  const breakevenTickets = computeBreakeven({
    avgPrice: avgTicketPrice ?? 0,
    avgPersonasPorEntrada,
    otherRevenuePerPerson: input.otherRevenuePerPerson,
    venueBarSharePercent,
    variableCostPerPerson: input.variableCostPerPerson,
    commissionPercent: input.commissionPercent,
    cardFeePercent: input.cardFeePercent,
    ivaApplies: input.ivaApplies,
    onlineSalesNoIva,
    fixedExpensesTotal: pnl.directExpensesTotal,
    extraNetContribution: extraIncomeTotal * ((input.ivaApplies && !onlineSalesNoIva ? 100 / 119 : 1) - input.cardFeePercent / 100) - extraVenueCost
  });
  const status = pnl.directExpensesTotal > maxDirectExpenses ? "danger" : maxDirectExpenses > 0 && pnl.directExpensesTotal > maxDirectExpenses * 0.9 ? "warning" : "ok";
  return {
    ticketsSold,
    attendance,
    ticketRevenue,
    otherRevenue,
    grossIncome,
    variableCostTotal,
    venueBarShare,
    extraIncomeTotal,
    extraVenueCost,
    fixedExpensesGross: input.expenseLines.reduce((sum2, l) => sum2 + expenseLineAmounts(l).total, 0),
    pnl,
    maxDirectExpenses,
    breakevenTickets,
    avgTicketPrice,
    status
  };
}

// shared/budgetInsights.ts
init_expenses();
var clone = (v) => JSON.parse(JSON.stringify(v));
var clp4 = (n2) => `$${Math.round(n2).toLocaleString("es-CL")}`;
var pct = (n2) => n2 == null ? "\u2014" : `${n2.toLocaleString("es-CL", { maximumFractionDigits: 1 })}%`;
function verdictFor(result) {
  if (result.pnl.netProfit < 0) return { key: "loss", label: "La fiesta da p\xE9rdida", short: "P\xE9rdida" };
  if (result.status === "danger") return { key: "danger", label: "Gana, pero bajo la meta de margen", short: "Bajo la meta" };
  if (result.status === "warning") return { key: "warning", label: "Cumple la meta, con poco margen de maniobra", short: "Cerca del l\xEDmite" };
  return { key: "ok", label: "Cumple la meta de margen", short: "Dentro del margen" };
}
