    text3(doc, `$${(s2.amount / r.grossIncome * 100).toLocaleString("es-CL", { maximumFractionDigits: 0 })}`, 684 + 140, sy, { size: 10, bold: true, color: C.ink, width: 70, align: "right" });
    hbar(doc, 684, sy + 17, 210, 7, s2.amount / r.grossIncome, C.orange);
