function pageSensitivity(doc, d) {
  newPage(doc, "light");
  header(doc, "Qu\xE9 mueve m\xE1s el margen", "D\xF3nde est\xE1 el riesgo y d\xF3nde est\xE1 la oportunidad", "Cu\xE1nto cambia la utilidad si cada factor empeora (rojo) o mejora (verde)");
  card2(doc, MX, 116, CONTENT_W, 384);
  const rows = d.sensitivity.slice(0, 6);
  const maxV = Math.max(1, ...rows.map((r) => Math.max(Math.abs(r.worseProfit), Math.abs(r.betterProfit))));
  const cx = 600, half = 250;
  const rowH = 50;
  rows.forEach((r, i) => {
    const y = 138 + i * rowH;
    text3(doc, r.label, MX + 24, y + 4, { size: 11.5, bold: true, color: C.ink, width: 270, height: 15 });
    text3(doc, r.change, MX + 24, y + 21, { size: 9.5, color: C.muted, width: 270 });
    const wl = Math.abs(r.worseProfit) / maxV * half;
    const wr = Math.abs(r.betterProfit) / maxV * half;
    rrect(doc, cx - wl, y + 4, Math.max(wl, 2), 26, 5, C.red);
    rrect(doc, cx, y + 4, Math.max(wr, 2), 26, 5, C.green);
    text3(doc, `-${compact(Math.abs(r.worseProfit))}`, cx - wl - 74, y + 11, { size: 10, bold: true, color: C.red, width: 68, align: "right" });
    text3(doc, `+${compact(r.betterProfit)}`, cx + wr + 6, y + 11, { size: 10, bold: true, color: C.green, width: 70 });
  });
  doc.save();
  doc.moveTo(cx, 130).lineTo(cx, 130 + rows.length * rowH).lineWidth(1.5).stroke(C.ink);
  doc.restore();
  const top = rows[0];
  if (top) fitText(doc, `Lo que m\xE1s pesa es \xAB${top.label}\xBB: ${top.change} mueve la utilidad entre ${compact(top.worseProfit)} y +${compact(top.betterProfit)}. Cuida eso primero.`, MX + 24, 448, { width: CONTENT_W - 48, height: 40, maxSize: 13, minSize: 10, bold: true, color: C.ink });
}
