async function buildSingleReportPdf(d, version) {
  const label = d.real ? `Informe real \xAB${d.name}\xBB` : version === "externa" ? `Proyecci\xF3n \xAB${d.name}\xBB` : `Simulaci\xF3n \xAB${d.name}\xBB`;
  const { doc, done } = createDoc(`${label} - Mansion Playroom`);
  const r = d.result;
  if (version === "externa") {
    cover(doc, {
      kicker: "Proyecci\xF3n de evento",
      title: d.name,
      subtitle: d.eventTitle ? `Evento: ${d.eventTitle}` : "Cifras proyectadas del evento",
      emittedAt: d.emittedAt,
      kpis: [
        { label: "Aforo estimado", value: `${r.attendance.toLocaleString("es-CL")} personas` },
        { label: "Entradas", value: r.ticketsSold.toLocaleString("es-CL"), caption: "entradas proyectadas" },
        { label: "Ingreso proyectado", value: compact(r.grossIncome), caption: "IVA incluido" }
      ]
    });
    pageIncome(doc, d, { kicker: "Ingresos", title: "De d\xF3nde viene el ingreso proyectado" });
    pageScenarios(doc, d, true);
    pageAssumptions(doc, { input: d.input, result: r }, { glossary: false, external: true });
    closingPage(doc);
    footers(doc, label, { skipLast: true });
    doc.end();
    return done;
  }
  const margin = r.pnl.marginPercent;
  cover(doc, {
    real: d.real,
    kicker: d.real ? "Informe real del evento" : "Informe de simulaci\xF3n",
    title: d.name,
    subtitle: d.real ? "Lo que realmente entr\xF3 y sali\xF3, con consejos para el pr\xF3ximo evento" : d.eventTitle ? `Vinculada al evento: ${d.eventTitle}` : "Simulaci\xF3n previa al evento: cu\xE1nto puedes gastar y cu\xE1nta gente necesitas",
    verdict: d.verdict,
    emittedAt: d.emittedAt,
    kpis: [
      { label: d.real ? "Ingreso real" : "Ingreso proyectado", value: compact(r.grossIncome), caption: `${r.attendance.toLocaleString("es-CL")} personas` },
      { label: d.real ? "Utilidad real" : "Utilidad estimada", value: compact(r.pnl.netProfit), caption: "despu\xE9s de todos los costos", color: r.pnl.netProfit >= 0 ? "#13795B" : "#C23B40" },
      { label: "Margen", value: pctText(margin), caption: `meta ${d.input.marginTargetPercent}%` }
    ]
  });
  if (version === "resumen") {
    pageExecutive(doc, d);
    footers(doc, label);
    doc.end();
    return done;
  }
  pageEssentials(doc, d);
  pageIncome(doc, d, { kicker: "De d\xF3nde viene la plata", title: "Tus ingresos, entrada por entrada" });
  pageMoneyOut(doc, d);
  pageCeiling(doc, d);
  pageScenarios(doc, d);
  if (d.sensitivity.length > 0) pageSensitivity(doc, d);
  pageRecommendations(doc, d);
  pageAssumptions(doc, { input: d.input, result: r, real: d.real }, { glossary: true });
  closingPage(doc);
  footers(doc, label, { skipLast: true });
  doc.end();
  return done;
}
