        orderId: order.id,
        orderItemId,
        eventId: order.eventId,
        ticketTypeId: type.id,
        holderName: order.buyerName,
        qrData: t2.qrData,
        qrImageUrl: t2.qrImageUrl,
        status: "valid",
        displayCode: t2.displayCode
