var AI_PHRASES_PROMPT_LINE = `Escribe como una persona de Playroom, no como un folleto: NO uses estas muletillas que suenan a IA: ${AI_PHRASES_ES.map((p) => `"${p.label}"`).join(", ")}, ni la estructura "no es solo X, es Y", ni rayas largas (\u2014). Di las cosas concretas: qu\xE9 pasa, cu\xE1ndo, d\xF3nde, cu\xE1nto.`;

// shared/captionCheck.ts
var INSTAGRAM_HASHTAG_LIMIT = 5;
var MONTHS_DAYS = new RegExp(String.raw`\b(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|octubre|noviembre|diciembre|lunes|martes|mi[eé]rcoles|jueves|viernes|s[aá]bado|domingo|hoy|ma[nñ]ana)\b`, "iu");
var ASK_VERBS = new RegExp(String.raw`\b(comenta|comenten|etiqueta|etiqueten|guarda|guarden|comparte|compartan|vota|voten|responde|respondan|compra|compren|escribe|escr[ií]banos|escr[ií]benos|reacciona|manda|mandanos|m[aá]ndanos|sigue|s[ií]guenos)\b`, "giu");
var URL_SPLIT = new RegExp(String.raw`(https?:\/\/\S+|www\.\S+)`, "giu");
function cleanAiMarks(text4) {
  return text4.split(URL_SPLIT).map((part, i) => {
    if (i % 2 === 1) return part;
    return part.replace(new RegExp(String.raw`[\u200B\u200C\u2060\u2061-\u2064\uFEFF\u00AD\u180E]`, "gu"), "").replace(new RegExp(String.raw`(\p{Extended_Pictographic})?([\u{E0000}-\u{E007F}]+)`, "gu"), (_m, emoji, tags) => emoji ? emoji + tags : "").replace(new RegExp(String.raw`(?<![\p{Extended_Pictographic}\uFE0F])\u200D|\u200D(?!\p{Extended_Pictographic})`, "gu"), "").replace(new RegExp(String.raw`[\u00A0\u202F]`, "gu"), " ").replace(new RegExp(String.raw`^[ \t]*—[ \t]*`, "gmu"), "").replace(new RegExp(String.raw`[ \t]*—[ \t]*`, "gu"), ", ").replace(new RegExp(String.raw`–`, "gu"), "-").replace(new RegExp(String.raw`…`, "gu"), "...").replace(new RegExp(String.raw`,\s*([,.;:!?])`, "gu"), "$1").replace(new RegExp(String.raw`[ \t]{2,}`, "gu"), " ").replace(new RegExp(String.raw`[ \t]+\n`, "gu"), "\n");
  }).join("");
}
function humanizeEs(text4) {
  const cleaned = cleanAiMarks(text4);
  const flags = [];
  for (const p of AI_PHRASES_ES) if (p.pattern.test(cleaned)) flags.push({ label: p.label, suggestion: p.suggestion });
  if (NOT_JUST_PATTERN.test(cleaned)) flags.push({ label: '"no es solo X, es Y"', suggestion: "decir directo lo que es" });
  const emojiBullets = cleaned.split("\n").filter((l) => new RegExp(String.raw`^\s*\p{Extended_Pictographic}`, "u").test(l)).length;
  if (emojiBullets >= 3) flags.push({ label: "lista con emojis de vi\xF1eta", suggestion: "menos vi\xF1etas, frases normales" });
  return { cleaned, flags };
}

