var WINBACK_SEGMENT_KEYS = ["fieles", "ultima", "una_vez", "dormidos"];
var WINBACK_SEGMENTS = [
  {
    key: "fieles",
    label: "Los de siempre",
    description: "Han comprado entrada para 3 o m\xE1s fiestas distintas.",
    objective: "Son clientes de la casa, de los que ya han venido muchas veces. H\xE1blales como a gente conocida: agradece que siempre est\xE9n, y cu\xE9ntales que viene una nueva fiesta. Que se sientan los primeros en enterarse, sin tono de campa\xF1a ni de oferta forzada."
  },
  {
    key: "ultima",
    label: "Estuvieron en la \xFAltima",
    description: "Compraron para la \xFAltima fiesta y todav\xEDa no son de los de siempre.",
    objective: 'Estuvieron en la \xFAltima fiesta, as\xED que la experiencia est\xE1 fresca. Dales las gracias por haber venido y cu\xE9ntales de la pr\xF3xima, con la idea de "esto se repite y se pone mejor". Inv\xEDtalos a volver y a traer a alguien.'
  },
  {
    key: "una_vez",
    label: "Vinieron una vez y no volvieron",
    description: "Compraron una sola vez, en una fiesta anterior a la \xFAltima.",
    objective: 'Vinieron una vez hace un tiempo y no han vuelto. Escr\xEDbeles con cercan\xEDa, sin reproche: "te echamos de menos". Cu\xE9ntales lo que viene de nuevo en la pr\xF3xima fiesta, para que tengan una raz\xF3n concreta para volver.'
  },
  {
    key: "dormidos",
    label: "Estuvieron en dos y se enfriaron",
    description: "Compraron para dos fiestas, pero ninguna fue la \xFAltima.",
    objective: "Vinieron a dos fiestas y hace rato que no los vemos. H\xE1blales como a alguien que ya conoce el ambiente y se perdi\xF3 las \xFAltimas: cu\xE9ntales qu\xE9 cambi\xF3 y por qu\xE9 esta vez vale la pena volver."
  }
];
var WINBACK_SEGMENT_BY_KEY = Object.fromEntries(WINBACK_SEGMENTS.map((s2) => [s2.key, s2]));
var WINBACK_LOYAL_MIN_EVENTS = 3;
function classifyWinback(input) {
  const { participation, latestPastEventId, targetEventId } = input;
  const segments = { fieles: [], ultima: [], una_vez: [], dormidos: [] };
  let alreadyBought = 0;
  let noPastEvents = 0;
  for (const [email, events2] of Array.from(participation.entries())) {
    if (events2.has(targetEventId)) {
      alreadyBought += 1;
      continue;
    }
    const past = new Set(Array.from(events2).filter((id) => id !== targetEventId));
    if (past.size === 0) {
      noPastEvents += 1;
      continue;
    }
    if (past.size >= WINBACK_LOYAL_MIN_EVENTS) segments.fieles.push(email);
    else if (latestPastEventId !== null && past.has(latestPastEventId)) segments.ultima.push(email);
    else if (past.size === 1) segments.una_vez.push(email);
    else segments.dormidos.push(email);
  }
  for (const key of WINBACK_SEGMENT_KEYS) segments[key].sort();
  return { segments, alreadyBought, noPastEvents };
}
function winbackCampaignName(segmentLabel, eventTitle) {
  return `Reactivaci\xF3n \xB7 ${segmentLabel} \xB7 ${eventTitle}`.slice(0, 255);
}
function winbackDaysToSend(recipients, dailyCap) {
  if (recipients <= 0 || dailyCap <= 0) return 0;
  return Math.ceil(recipients / dailyCap);
}
function winbackCtaUrl(baseUrl, eventSlug, segmentKey) {
  const params = new URLSearchParams({ utm_source: "email", utm_medium: "mailing", utm_campaign: `reactivacion-${segmentKey}` });
  return `${baseUrl.replace(/\/$/, "")}/checkout/${eventSlug}?${params.toString()}`;
}

// server/winback.ts
var clp9 = (n2) => `$${Math.round(n2).toLocaleString("es-CL")}`;
async function resolveTargetEvent(targetEventId, now) {
  const event = targetEventId ? await getEventById(targetEventId) : await getFeaturedEvent();
  if (!event) throw new Error("No hay ning\xFAn evento publicado al que invitar.");
  if (new Date(event.eventDate).getTime() <= now.getTime()) {
    throw new Error(`"${event.title}" ya pas\xF3. Elige un evento que todav\xEDa no ocurra.`);
  }
  return event;
}
async function getWinbackOverview(targetEventId, now = /* @__PURE__ */ new Date()) {
  const event = await resolveTargetEvent(targetEventId, now);
  const emailsBySegment = await segmentEmails(event.id, now);
  const segments = [];
  for (const def of WINBACK_SEGMENTS) {
    segments.push({
      key: def.key,
      label: def.label,
      description: def.description,
      count: (await getCustomerIdsByEmails(emailsBySegment.segments[def.key])).length
    });
  }
  return {
    event: { id: event.id, title: event.title, slug: event.slug, eventDate: new Date(event.eventDate).toISOString() },
    latestPastEvent: emailsBySegment.latestPastTitle,
    segments,
    alreadyBought: emailsBySegment.alreadyBought,
    dailyCap: AUTOMATED_EMAIL_DAILY_CAP
  };
}
async function segmentEmails(targetEventId, now = /* @__PURE__ */ new Date()) {
  const { participation, pastEvents } = await getWinbackData(now);
  const latest = pastEvents.find((e) => e.id !== targetEventId) ?? null;
  const countable = /* @__PURE__ */ new Set([targetEventId, ...pastEvents.map((e) => e.id)]);
  const onlyPast = /* @__PURE__ */ new Map();
  participation.forEach((events2, email) => {
    onlyPast.set(email, new Set(Array.from(events2).filter((id) => countable.has(id))));
  });
  const classified = classifyWinback({ participation: onlyPast, latestPastEventId: latest?.id ?? null, targetEventId });
  return { ...classified, latestPastTitle: latest?.title ?? null };
}
async function buildEventFacts(event) {
  const date = new Date(event.eventDate);
  const lines = [
    `- Evento: ${event.title}`,
    `- Fecha: ${formatChileDate(date, { withWeekday: true })}, ${formatChileTime(date)} hrs`
  ];
  if (event.venue) lines.push(`- Lugar: ${event.venue}`);
  if (event.shortDescription) lines.push(`- De qu\xE9 se trata: ${event.shortDescription.slice(0, 300)}`);
  const mix = (await getAccessTicketMix(event.id)).filter((t2) => t2.status === "active" && Number(t2.price) > 0);
  if (mix.length > 0) {
    const cheapest = mix.reduce((a, b) => Number(b.price) < Number(a.price) ? b : a);
    lines.push(`- Entradas desde ${clp9(Number(cheapest.price))} (${cheapest.name}), precio de la tanda actual.`);
    const limited = mix.filter((t2) => !isUnlimitedStock(Number(t2.totalStock)));
    if (limited.length > 0) lines.push("- Hay cupos limitados en algunos accesos.");
  }
  const schedule = normalizeTandaSchedule(event.tandaDiscountSchedule);
  const current = schedule[event.tandaPhaseIndex];
  const next = nextPhase(event.tandaPhaseIndex, schedule);
  if (next && current) {
    lines.push(current.untilDate ? `- El precio actual rige hasta el ${formatChileDate(new Date(current.untilDate), { withWeekday: true })}; despu\xE9s sube.` : "- El precio actual es de esta tanda y sube cuando se cierre.");
  }
  return lines.join("\n");
}
async function draftWinbackEmail(segmentKey, targetEventId, now = /* @__PURE__ */ new Date()) {
  const event = await resolveTargetEvent(targetEventId, now);
  const segment = WINBACK_SEGMENT_BY_KEY[segmentKey];
  const facts = await buildEventFacts(event);
  const objective = [
    segment.objective,
    "",
    "Datos reales del pr\xF3ximo evento (usa SOLO estos datos; no inventes precios, fechas, shows ni invitados):",
    facts,
    "",
    'Reglas del correo: un solo bot\xF3n de compra y nada de links dentro del texto; tono cercano y c\xE1lido, sin desesperaci\xF3n ni "\xFAltima oportunidad"; si hay urgencia real (el precio sube), dila una sola vez como un dato \xFAtil; no menciones cu\xE1ntas veces compr\xF3 la persona ni nada de su historial.'
  ].join("\n");
  return generateMailingTemplate(objective, segment.description);
}
async function createWinbackCampaign(input, now = /* @__PURE__ */ new Date()) {
  const content = MailingContentSchema.safeParse(input.content);
  if (!content.success) {
    throw new Error(`El correo no tiene el formato esperado: ${content.error.issues[0]?.message ?? "revisa los campos"}.`);
  }
  const event = await resolveTargetEvent(input.targetEventId, now);
  const segment = WINBACK_SEGMENT_BY_KEY[input.segmentKey];
  const name = winbackCampaignName(segment.label, event.title);
  const existing = (await listMailingCampaigns()).find((c) => c.name === name && c.status !== "cancelled");
  if (existing) {
    throw new Error("Ya hay una campa\xF1a de este grupo para este evento. Canc\xE9lala desde el historial de Mailing si quieres armar otra.");
  }
  const { segments } = await segmentEmails(event.id, now);
  const customerIds = await getCustomerIdsByEmails(segments[input.segmentKey]);
  if (customerIds.length === 0) throw new Error("Este grupo no tiene a nadie por ahora.");
  const { campaignId } = await createAutoMailingCampaign({
    name,
    audienceDescription: segment.description,
    customerIds,
    content: content.data,
    ctaUrl: winbackCtaUrl(EMAIL_BASE_URL, event.slug, input.segmentKey),
    eventId: event.id
  });
  return { campaignId, recipients: customerIds.length, days: winbackDaysToSend(customerIds.length, AUTOMATED_EMAIL_DAILY_CAP) };
}

