      fallbacks: "default",
      system: [
        { type: "text", text: STABLE_SYSTEM, cache_control: { type: "ephemeral" } },
        { type: "text", text: opts.dynamic }
      ],
      messages: opts.messages,
      output_config: { ...opts.model === "claude-haiku-4-5" ? {} : { effort: "medium" }, format: { type: "json_schema", schema: opts.schema } }
