import { eq as eq27 } from "drizzle-orm";
async function redeemDisplayCode(db, params) {
  const code = params.displayCode.trim().toUpperCase();
  const { result, conflictNote } = await applyOp(
    db,
    {
      id: params.opId,
      type: "redeem",
      eventId: params.eventId,
      operatorId: params.operatorId,
      registerId: params.registerId,
      targetType: "ticket",
      targetId: code,
      payload: { displayCode: code },
      clientAt: params.clientAt
    },
    async () => {
      const [ticket] = await db.select().from(tickets).where(eq27(tickets.displayCode, code)).limit(1);
      if (!ticket) return { result: "rejected", conflictNote: "El c\xF3digo no existe" };
      const [gift] = await db.select().from(partyGifts).where(eq27(partyGifts.ticketId, ticket.id)).limit(1);
      let carriedFromEventId = null;
      if (!gift && ticket.eventId !== params.eventId) {
        const [originEvent] = await db.select().from(events).where(eq27(events.id, ticket.eventId)).limit(1);
        if (originEvent?.status !== "past") {
          return { result: "rejected", conflictNote: "El c\xF3digo no corresponde a este evento" };
        }
        carriedFromEventId = ticket.carriedFromEventId ?? ticket.eventId;
      }
      if (ticket.status === "cancelled") return { result: "rejected", conflictNote: "El c\xF3digo fue anulado" };
      if (ticket.status === "used") {
        return { result: "conflict", conflictNote: `Ya fue canjeado el ${ticket.usedAt?.toISOString?.() ?? ticket.usedAt}` };
      }
      await db.update(tickets).set({
        status: "used",
        usedAt: /* @__PURE__ */ new Date(),
        usedByOperatorId: params.operatorId,
        usedAtRegisterId: params.registerId ?? null,
        ...carriedFromEventId !== null ? { eventId: params.eventId, carriedFromEventId } : {}
      }).where(eq27(tickets.id, ticket.id));
      if (gift) {
        await db.update(partyGifts).set({ status: "redeemed", redeemedAt: /* @__PURE__ */ new Date() }).where(eq27(partyGifts.id, gift.id));
      }
      return { result: "applied" };
    }
  );
  return { result, conflictNote };
}

