var clip3 = (v, max) => typeof v === "string" ? v.trim().slice(0, max) : "";
async function generateProfileAudit(input, now = /* @__PURE__ */ new Date()) {
  const event = await getFeaturedEvent();
  const facts = event ? await buildEventFacts(event) : "(no hay un evento destacado publicado)";
  const insightsSummary = insightsPromptSummary(await getInstagramInsights());
  const lines = [
    "PERFIL ACTUAL (lo que el due\xF1o carg\xF3):",
    `- Usuario: ${clip3(input.username, 60) || "(no cargado)"}`,
    `- Nombre del perfil: ${clip3(input.name, 100) || "(no cargado)"}`,
    `- Bio: ${clip3(input.bio, 400) || "(no cargada)"}`,
    `- Link de la bio: ${clip3(input.link, 300) || "(no cargado)"}`,
    ...input.followers != null ? [`- Seguidores: ${input.followers}`] : [],
    ...input.posts != null ? [`- Publicaciones: ${input.posts}`] : [],
    `- Historias destacadas: ${input.highlights.map((h) => clip3(h, 40)).filter(Boolean).join(", ") || "(no cargadas)"}`,
    `- Captura del perfil: ${input.screenshotUrl ? "s\xED, adjunta" : "no"}`,
    "",
    "PR\xD3XIMO EVENTO (datos reales para las bios):",
    facts,
    `- Dress code: ${EVENT_BRAND.dressCode}`,
    "",
    ...insightsSummary ? [insightsSummary, ""] : [],
    "LO QUE PLAYROOM EXPLICA EN SU SITIO (el perfil debe ser coherente con esto):",
    buildPlayroomKnowledge()
  ];
  const userContent = input.screenshotUrl ? [{ type: "text", text: lines.join("\n") }, { type: "image_url", image_url: { url: input.screenshotUrl } }] : lines.join("\n");
  const result = await invokeLLM({
    feature: "profileAudit",
    messages: [
      { role: "system", content: SYSTEM_PROMPT7 },
      { role: "user", content: userContent }
    ],
    responseFormat: { type: "json_schema", json_schema: AUDIT_SCHEMA },
    maxTokens: 4e3,
    ...ENV.anthropicApiKey ? { model: AUDIT_MODEL, thinking: NO_THINKING } : {}
  });
  const parsed = JSON.parse(extractContent(result.choices[0]?.message ?? { content: "" }));
  const { items, total, level } = scoreProfile(parsed.items);
  const bios = (Array.isArray(parsed.bios) ? parsed.bios : []).filter((b) => typeof b === "string" && b.trim().length > 0).map((b) => humanizeEs(b.trim()).cleaned).map((b) => Array.from(b).slice(0, BIO_MAX_CHARS).join("")).slice(0, 3);
  if (items.every((i) => i.score === 0) && bios.length === 0) throw new Error("La IA no devolvi\xF3 una revisi\xF3n v\xE1lida. Intenta de nuevo.");
  return {
    generatedAt: now.toISOString(),
    items: items.map((i) => ({ ...i, note: cleanAiMarks(i.note) })),
    total,
    level,
    summary: cleanAiMarks(clip3(parsed.summary, 800)),
    bios,
    fixes: (Array.isArray(parsed.fixes) ? parsed.fixes : []).filter((f) => typeof f === "string" && f.trim().length > 0).map((f) => cleanAiMarks(f.trim().slice(0, 300))).slice(0, 6)
  };
}

