// shared/instagramShowcaseConfig.ts
var CANDYLAND_INSTAGRAM_HANDLE = "mansionplayroom.cl";

// server/instagramFeed.ts
var TTL_MS2 = 60 * 60 * 1e3;
var cache3 = null;
var inFlight = null;
async function load2() {
  const [profile, media] = await Promise.all([
    fetchOwnProfile().catch(() => null),
    fetchOwnMedia(SHOWCASE_MEDIA_LIMIT + 3).catch(() => [])
  ]);
  const settings = await getSiteSettings().catch(() => null);
  return {
    profile: {
      username: profile?.username ?? CANDYLAND_INSTAGRAM_HANDLE,
      name: profile?.name ?? "Mansion Playroom",
      bio: profile?.bio ?? "",
      picture: profile?.picture ?? null,
      followers: profile?.followers ?? settings?.instagramFollowers ?? 0,
      posts: profile?.posts ?? settings?.instagramPosts ?? 0
    },
    media: normalizeMedia(media)
  };
}
async function getInstagramShowcase(now = Date.now()) {
  if (cache3 && now - cache3.at < TTL_MS2) return cache3.data;
  if (!inFlight) {
    inFlight = load2().then((data) => {
      const merged = data.media.length === 0 && cache3 ? { ...data, media: cache3.data.media } : data;
      cache3 = { at: Date.now(), data: merged };
      return merged;
    }).finally(() => {
      inFlight = null;
    });
  }
  return inFlight;
}

// server/orderRefund.ts
init_schema();
init_db();
init_email();
import { and as and35, eq as eq40, sql as sql19 } from "drizzle-orm";

// shared/orderRefund.ts
var REFUND_DEADLINE_DAYS = 5;
function isPastRefundDeadline(eventDate, now = /* @__PURE__ */ new Date()) {
  const msLeft = new Date(eventDate).getTime() - now.getTime();
  return msLeft < REFUND_DEADLINE_DAYS * 24 * 36e5;
}
function refundAmountForPercent(paid, percent) {
  const pct2 = Math.min(100, Math.max(0, percent));
  return Math.round(paid * pct2 / 100);
}
function refundPercentForAmount(paid, amount) {
  if (paid <= 0) return 0;
  return Math.round(amount / paid * 1e4) / 100;
}

// server/orderRefund.ts
function paidOf(order) {
  return Number(order.total) + (order.missionTopupStatus === "paid" ? Number(order.missionTopupAmount ?? 0) : 0);
}
async function refundOrder(input) {
  const db = await getDb();
  if (!db) throw new Error("Base de datos no disponible");
  const [order] = await db.select().from(orders).where(eq40(orders.id, input.orderId)).limit(1);
  if (!order) throw new Error("No encontr\xE9 esa orden.");
  if (order.paymentStatus !== "approved") throw new Error("Solo se puede devolver una compra aprobada.");
  if (order.channel !== "web") throw new Error("Solo las compras web se devuelven ac\xE1; las de caja se anulan desde la caja.");
  if (order.missionDeposit === 1 && order.missionTopupStatus !== "paid") {
    throw new Error("Esta compra es un abono de la Misi\xF3n 300 con diferencia pendiente; resu\xE9lvela primero.");
  }
  const [event] = await db.select({ title: events.title, eventDate: events.eventDate }).from(events).where(eq40(events.id, order.eventId)).limit(1);
  if (!event) throw new Error("No encontr\xE9 el evento de esta compra.");
  if (!input.overrideDeadline && isPastRefundDeadline(event.eventDate)) {
    throw new Error(`Faltan menos de ${REFUND_DEADLINE_DAYS} d\xEDas para el evento: fuera del plazo de devoluci\xF3n. Puedes saltarte el plazo marcando la casilla.`);
  }
  const paid = paidOf(order);
  if (paid <= 0) throw new Error("Esta compra no tiene monto pagado para devolver.");
  const refundAmount = input.amount != null ? Math.round(input.amount) : refundAmountForPercent(paid, input.percent ?? 0);
  if (!(refundAmount > 0)) throw new Error("El monto a devolver debe ser mayor a $0.");
  if (refundAmount > paid) throw new Error("No puedes devolver m\xE1s de lo que pag\xF3 el cliente.");
  const refundPercent = input.amount != null ? refundPercentForAmount(paid, refundAmount) : Math.min(100, Math.max(0, input.percent ?? 0));
  const orderTickets = await db.select({ id: tickets.id, status: tickets.status }).from(tickets).where(eq40(tickets.orderId, order.id));
  if (orderTickets.some((t2) => t2.status === "used")) throw new Error("Una de las entradas ya se us\xF3 en la puerta; no se puede devolver.");
  const [credit] = await db.select({ id: accessCredits.id }).from(accessCredits).where(and35(eq40(accessCredits.originOrderId, order.id), sql19`${accessCredits.status} != 'cancelled'`)).limit(1);
  if (credit) throw new Error("A esta compra ya se le dej\xF3 un cr\xE9dito para otra fecha; no se puede devolver tambi\xE9n.");
  const [prepaid] = await db.select({ id: prepaidLedger.id }).from(prepaidLedger).where(eq40(prepaidLedger.orderId, order.id)).limit(1);
  if (prepaid) throw new Error("Esta compra movi\xF3 saldo PlayCard (recarga); no se devuelve desde ac\xE1.");
  const reason = (input.reason ?? "").trim().slice(0, 500) || null;
  const [updateResult] = await db.update(orders).set({
    paymentStatus: "refunded",
    refundAmount: String(refundAmount),
    refundPercent: String(refundPercent),
    refundReason: reason,
    refundedAt: /* @__PURE__ */ new Date()
  }).where(and35(eq40(orders.id, order.id), eq40(orders.paymentStatus, "approved")));
  if (updateResult?.affectedRows === 0) {
    throw new Error("Esta compra ya hab\xEDa sido devuelta.");
  }
  await db.update(tickets).set({ status: "cancelled" }).where(and35(eq40(tickets.orderId, order.id), eq40(tickets.status, "valid")));
  const items = await db.select().from(orderItems).where(eq40(orderItems.orderId, order.id));
  for (const item of items) {
    await db.update(ticketTypes).set({ soldCount: sql19`GREATEST(soldCount - ${item.quantity}, 0)` }).where(eq40(ticketTypes.id, item.ticketTypeId));
  }
  const commissions = await db.select({ id: ambassadorCommissions.id, amount: ambassadorCommissions.commissionAmount }).from(ambassadorCommissions).where(eq40(ambassadorCommissions.orderId, order.id));
  if (commissions.length > 0) await db.delete(ambassadorCommissions).where(eq40(ambassadorCommissions.orderId, order.id));
  if (order.discountCodeId) {
    await db.update(discountCodes).set({ usedCount: sql19`GREATEST(usedCount - 1, 0)` }).where(eq40(discountCodes.id, order.discountCodeId));
  }
  if (order.communityCodeId) {
    await db.update(communityCodes).set({ usedCount: sql19`GREATEST(usedCount - 1, 0)` }).where(eq40(communityCodes.id, order.communityCodeId));
  }
  try {
    const earned = await db.select().from(playcoinsLedger).where(eq40(playcoinsLedger.orderId, order.id));
    for (const row of earned) {
      if (row.delta !== 0) await adjustPlaycoinsManually(row.customerId, -row.delta, `Orden #${order.orderNumber} devuelta`);
    }
    const email = order.buyerEmail.trim().toLowerCase();
    const [customer] = await db.select().from(customers).where(eq40(customers.email, email)).limit(1);
    if (customer) {
      await db.update(customers).set({
        totalSpent: String(Math.max(0, Number(customer.totalSpent) - refundAmount))
      }).where(eq40(customers.id, customer.id));
    }
  } catch (err) {
    console.error("[orderRefund] no se pudieron ajustar playcoins/cliente", err);
  }
  await recordAdminAudit({
    action: "order.refund",
    targetType: "order",
    targetId: order.id,
    eventId: order.eventId,
    ip: input.ip,
    payload: {
      orderNumber: order.orderNumber,
      paid,
      refundAmount,
      refundPercent,
      reason,
      overrideDeadline: Boolean(input.overrideDeadline),
      commissionRemoved: commissions.map((c) => Number(c.amount))
    }
  });
  const emailSent = await sendRefundEmail({
    to: order.buyerEmail,
    buyerName: order.buyerName,
    eventTitle: event.title,
    orderNumber: order.orderNumber,
    paid,
    refundAmount,
    refundPercent
  });
  return { refundAmount, refundPercent, retained: paid - refundAmount, emailSent };
}
async function sendRefundEmail(data) {
  try {
    const { to, ...rest } = data;
    const result = await sendEmail({ to, subject: "Registramos la devoluci\xF3n de tu compra \u{1F4B8}", html: buildOrderRefundEmail(rest) });
    return Boolean(result?.success);
  } catch (err) {
    console.error("[orderRefund] no se pudo mandar el correo", err);
    return false;
  }
}

