import { and as and36, desc as desc20, eq as eq41, inArray as inArray22, sql as sql20 } from "drizzle-orm";
var CREDIT_CUSTOMER_TAG = "Cr\xE9dito de acceso";
async function insertCreditWithUniqueCode(db, values) {
  for (let attempt = 0; attempt < 8; attempt++) {
    const code = generateCreditCode();
    try {
      await db.insert(accessCredits).values({ ...values, code });
      return code;
    } catch (err) {
      const duplicate = err?.code === "ER_DUP_ENTRY" || /duplicate entry/i.test(String(err?.message ?? ""));
      if (!duplicate) throw err;
    }
  }
  throw new Error("No se pudo generar un c\xF3digo \xFAnico, intenta de nuevo.");
}
async function issueAccessCreditsForOrder(orderId, actor = {}) {
  const db = await getDb();
  if (!db) throw new Error("Base de datos no disponible");
  const [order] = await db.select().from(orders).where(eq41(orders.id, orderId)).limit(1);
  if (!order) throw new Error("No encontr\xE9 esa orden.");
  if (order.paymentStatus !== "approved") throw new Error("Solo se puede dejar cr\xE9dito de una compra aprobada.");
  if (order.channel === "caja") throw new Error("Las ventas de caja no tienen cr\xE9dito de acceso.");
  if (order.missionDeposit === 1 && order.missionTopupStatus !== "paid") {
    throw new Error("Esta compra es un abono de la Misi\xF3n 300 con diferencia pendiente; resu\xE9lvela primero.");
  }
  const accessItems = await db.select({
    ticketTypeId: orderItems.ticketTypeId,
    quantity: orderItems.quantity,
    accesoSlug: ticketTypes.accesoSlug,
    name: ticketTypes.name
  }).from(orderItems).innerJoin(ticketTypes, eq41(orderItems.ticketTypeId, ticketTypes.id)).where(and36(eq41(orderItems.orderId, orderId), eq41(ticketTypes.category, "acceso")));
  const usable = accessItems.filter((i) => i.accesoSlug);
  if (usable.length === 0) throw new Error("Esta orden no tiene un acceso al que dejarle cr\xE9dito.");
  const accessTypeIds = usable.map((i) => i.ticketTypeId);
  const orderTickets = await db.select({ id: tickets.id, status: tickets.status }).from(tickets).where(and36(eq41(tickets.orderId, orderId), inArray22(tickets.ticketTypeId, accessTypeIds)));
  if (orderTickets.some((t2) => t2.status === "used")) throw new Error("Una de las entradas ya se us\xF3 en la puerta; no se puede dejar cr\xE9dito.");
  const [existing] = await db.select({ id: accessCredits.id }).from(accessCredits).where(and36(eq41(accessCredits.originOrderId, orderId), sql20`${accessCredits.status} != 'cancelled'`)).limit(1);
  if (existing) throw new Error("Ya se dej\xF3 cr\xE9dito para esta orden.");
  const issued = [];
  for (const item of usable) {
    for (let i = 0; i < item.quantity; i++) {
      const code = await insertCreditWithUniqueCode(db, {
        accesoSlug: item.accesoSlug,
        accesoName: item.name,
        buyerEmail: order.buyerEmail.trim().toLowerCase(),
        buyerName: order.buyerName,
        originOrderId: orderId,
        originEventId: order.eventId,
        note: `Dejado para otra fecha (orden ${order.orderNumber})`
      });
      issued.push({ code, accesoName: item.name });
    }
  }
  await db.update(tickets).set({ status: "cancelled" }).where(and36(eq41(tickets.orderId, orderId), inArray22(tickets.ticketTypeId, accessTypeIds), eq41(tickets.status, "valid")));
  for (const item of usable) {
    await db.update(ticketTypes).set({ soldCount: sql20`GREATEST(soldCount - ${item.quantity}, 0)` }).where(eq41(ticketTypes.id, item.ticketTypeId));
  }
  try {
    const [customer] = await db.select({ id: customers.id }).from(customers).where(eq41(customers.email, order.buyerEmail.trim().toLowerCase())).limit(1);
    if (customer) await addCustomerTag(customer.id, CREDIT_CUSTOMER_TAG);
  } catch (err) {
    console.error("[accessCredit] no se pudo etiquetar al cliente", err);
  }
  await recordAdminAudit({
    action: "accessCredit.issue",
    targetType: "order",
    targetId: orderId,
    eventId: order.eventId,
    ip: actor.ip,
    payload: { orderNumber: order.orderNumber, codes: issued.map((c) => c.code) }
  });
  const [event] = await db.select({ title: events.title }).from(events).where(eq41(events.id, order.eventId)).limit(1);
  const emailSent = await sendCreditEmail(order.buyerEmail, order.buyerName, event?.title ?? "la fiesta", issued, false);
  return { codes: issued, emailSent };
}
async function sendCreditEmail(to, buyerName, originEventTitle, credits, reminder) {
  try {
    const result = await sendEmail({
      to,
      subject: reminder ? "Recuerda: tu acceso guardado te espera \u{1F39F}\uFE0F" : "Tu acceso qued\xF3 guardado para un pr\xF3ximo evento \u{1F39F}\uFE0F",
      html: buildAccessCreditEmail({ buyerName, originEventTitle, credits, reminder })
    });
    return Boolean(result?.success);
  } catch (err) {
    console.error("[accessCredit] no se pudo mandar el correo", err);
    return false;
  }
}
async function withAvailability(credits) {
  const db = await getDb();
  if (!db || credits.length === 0) return [];
  const orderIds = Array.from(new Set(credits.map((c) => c.usedOrderId).filter((id) => id != null)));
  const eventIds = Array.from(new Set(credits.map((c) => c.originEventId)));
  const [usedOrders, eventRows] = await Promise.all([
    orderIds.length ? db.select({ id: orders.id, paymentStatus: orders.paymentStatus, createdAt: orders.createdAt }).from(orders).where(inArray22(orders.id, orderIds)) : [],
    db.select({ id: events.id, title: events.title }).from(events).where(inArray22(events.id, eventIds))
  ]);
  const orderById = new Map(usedOrders.map((o) => [o.id, o]));
  const eventTitle = new Map(eventRows.map((e) => [e.id, e.title]));
  return credits.map((c) => ({
    id: c.id,
    code: c.code,
    accesoName: c.accesoName,
    buyerName: c.buyerName,
    buyerEmail: c.buyerEmail,
    originOrderId: c.originOrderId,
    originEventTitle: eventTitle.get(c.originEventId) ?? null,
    availability: creditAvailability(c, c.usedOrderId ? orderById.get(c.usedOrderId) ?? null : null),
    createdAt: c.createdAt
  }));
}
async function listCreditsByOrderIds(orderIds) {
  try {
    const db = await getDb();
    if (!db || orderIds.length === 0) return [];
    return withAvailability(await db.select().from(accessCredits).where(inArray22(accessCredits.originOrderId, orderIds)).orderBy(desc20(accessCredits.createdAt)));
  } catch {
    return [];
  }
}
async function listAccessCredits() {
  try {
    const db = await getDb();
    if (!db) return [];
    const rows = await withAvailability(await db.select().from(accessCredits).orderBy(desc20(accessCredits.createdAt)).limit(200));
    return rows.sort((a, b) => Number(b.availability === "available") - Number(a.availability === "available"));
  } catch {
    return [];
  }
}
async function remindAccessCredit(creditId) {
  const db = await getDb();
  if (!db) throw new Error("Base de datos no disponible");
  const [credit] = await db.select().from(accessCredits).where(eq41(accessCredits.id, creditId)).limit(1);
  if (!credit) throw new Error("No encontr\xE9 ese cr\xE9dito.");
  const mine = await withAvailability(await db.select().from(accessCredits).where(eq41(accessCredits.originOrderId, credit.originOrderId)));
  const available = mine.filter((c) => c.availability === "available");
  if (available.length === 0) throw new Error("Ese cr\xE9dito ya fue usado o cancelado.");
  const sent = await sendCreditEmail(credit.buyerEmail, credit.buyerName ?? "hola", available[0].originEventTitle ?? "la fiesta", available.map((c) => ({ code: c.code, accesoName: c.accesoName })), true);
  return { sent };
}

