async function getContentDesign(id) {
  const db = await requireDb4();
  const [row] = await db.select().from(contentDesigns).where(eq42(contentDesigns.id, id)).limit(1);
  return row && row.kind !== "ia" ? toStored(row) : null;
}
async function saveContentDesign(id, raw) {
  const design = normalizeStudioDesign(raw);
  if (!design) throw new Error("El dise\xF1o no tiene ninguna l\xE1mina.");
  const db = await requireDb4();
  const values = {
    eventId: design.eventId,
    title: design.title,
    format: design.format,
    theme: design.theme,
    data: { slides: design.slides, caption: design.caption, showBrand: design.showBrand }
  };
  if (id != null) {
    const [existing] = await db.select({ id: contentDesigns.id, kind: contentDesigns.kind }).from(contentDesigns).where(eq42(contentDesigns.id, id)).limit(1);
    if (!existing) throw new Error("Ese dise\xF1o ya no existe.");
    if (existing.kind === "ia") throw new Error("Ese dise\xF1o es del Dise\xF1ador IA: se edita desde ah\xED.");
    await db.update(contentDesigns).set(values).where(eq42(contentDesigns.id, id));
    return id;
  }
  const [result] = await db.insert(contentDesigns).values(values);
  return result.insertId;
}
async function deleteContentDesign(id) {
  const db = await requireDb4();
  await db.delete(contentDesignMessages).where(eq42(contentDesignMessages.designId, id));
  await db.delete(contentDesigns).where(eq42(contentDesigns.id, id));
}

