async function quickBubbleDesign(input) {
  const facts = await eventFacts(input.eventId);
  const count2 = Math.max(1, Math.min(10, input.format === "carrusel" ? input.slideCount : 1));
  const message = await getAnthropicClient().messages.create({
    model: input.model,
    max_tokens: 3e3,
    system: [
      { type: "text", text: SYSTEM, cache_control: { type: "ephemeral" } },
      { type: "text", text: `Datos reales del evento (no inventes fechas ni precios):
${facts}` }
    ],
    messages: [{ role: "user", content: `Pedido: ${input.brief}
L\xE1minas: ${count2}` }],
    output_config: { format: { type: "json_schema", schema: SCHEMA2 } }
  });
  const msg = message;
  if (msg.stop_reason === "refusal") throw new Error("La IA no quiso hacer este dise\xF1o. Prueba describi\xE9ndolo de otra forma.");
  if (msg.stop_reason === "max_tokens") throw new Error("La IA se qued\xF3 sin espacio. Pide menos l\xE1minas.");
  const usage = addUsage(EMPTY_USAGE, {
    inputTokens: msg.usage.input_tokens ?? 0,
    outputTokens: msg.usage.output_tokens ?? 0,
    cacheReadTokens: msg.usage.cache_read_input_tokens ?? 0,
    cacheWriteTokens: msg.usage.cache_creation_input_tokens ?? 0
  });
  let data;
  try {
    data = JSON.parse(msg.content.map((b) => b.text ?? "").join(""));
  } catch {
    throw new Error("La IA devolvi\xF3 una respuesta rota. Intenta de nuevo.");
  }
  const design = normalizeStudioDesign({
    title: data.title,
    format: input.format,
    theme: DEFAULT_STUDIO_THEME,
    eventId: input.eventId,
    caption: data.caption,
    slides: data.slides
  });
  if (!design) throw new Error("La IA no arm\xF3 ninguna l\xE1mina. Intenta de nuevo.");
  return { design, usage, costUsd: usageCostUsd(msg.model, usage), model: msg.model };
}

