// server/googleDrive.ts
var driveThumbUrl = (id, width = 600) => `https://drive.google.com/thumbnail?id=${encodeURIComponent(id)}&sz=w${width}`;
var driveDownloadUrl = (id) => `https://drive.google.com/uc?export=download&id=${encodeURIComponent(id)}`;
function parseDriveFolderId(input) {
  const text4 = input.trim();
  if (!text4) return null;
  const folder = text4.match(/\/folders\/([A-Za-z0-9_-]{10,})/);
  if (folder) return folder[1];
  const param = text4.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (param) return param[1];
  if (/^[A-Za-z0-9_-]{20,}$/.test(text4)) return text4;
  return null;
}
function withUrls(files) {
  return files.map((f) => ({ ...f, thumbUrl: driveThumbUrl(f.id), downloadUrl: driveDownloadUrl(f.id) }));
}
async function listDriveMedia(folderUrlOrId, apiKey = process.env.GOOGLE_API_KEY) {
  if (!apiKey) {
    throw new Error("Falta configurar GOOGLE_API_KEY en Vercel para leer la carpeta de Drive.");
  }
  const folderId = parseDriveFolderId(folderUrlOrId);
  if (!folderId) throw new Error("El link no parece ser una carpeta de Google Drive.");
  const params = new URLSearchParams({
    q: `'${folderId}' in parents and trashed = false and (mimeType contains 'image/' or mimeType contains 'video/')`,
    fields: "files(id,name,mimeType)",
    orderBy: "createdTime desc",
    pageSize: "50",
    key: apiKey
  });
  let res;
  try {
    res = await fetch(`https://www.googleapis.com/drive/v3/files?${params}`);
  } catch {
    throw new Error("No se pudo conectar con Google Drive. Intenta de nuevo en un momento.");
  }
  if (res.status === 403 || res.status === 404) {
    throw new Error('No se puede leer la carpeta. Comp\xE1rtela como "Cualquier persona con el enlace" (Lector) y revisa que la API key tenga habilitada la Google Drive API.');
  }
  if (!res.ok) throw new Error(`Google Drive respondi\xF3 con un error (${res.status}).`);
  const body = await res.json();
  const files = (body.files ?? []).filter((f) => f?.id && f?.name);
  if (files.length === 0) throw new Error("La carpeta no tiene fotos ni videos.");
  return withUrls(files);
}

