  // Encuesta post-fiesta, lado PÚBLICO (server/eventSurvey.ts): la persona
  // llega con el token secreto de su correo. El token es de 192 bits, así que
  // no se adivina; igual se limita por IP el envío, como los demás
  // formularios públicos. Nunca devuelve el correo de nadie.
  survey: router({
    get: publicProcedure.input(z8.object({ token: z8.string().min(8).max(64) })).query(async ({ input }) => {
      const row = await getSurveyByToken(input.token);
      if (!row) throw new TRPCError3({ code: "NOT_FOUND", message: "Este link de la encuesta no es v\xE1lido." });
      return {
        eventTitle: row.eventTitle,
        eventDate: row.eventDate,
        firstName: (row.buyerName ?? "").trim().split(" ")[0] || null,
        answered: row.respondedAt != null
      };
    }),
    submit: publicProcedure.input(z8.object({
      token: z8.string().min(8).max(64),
      rating: z8.number().int().min(1).max(5),
      liked: z8.string().max(2e3).optional(),
      improve: z8.string().max(2e3).optional()
    })).mutation(async ({ input, ctx }) => {
      const ipKey = `survey-submit:${clientIp(ctx)}`;
      if (!await checkIpRateLimit(ipKey)) {
        throw new TRPCError3({ code: "TOO_MANY_REQUESTS", message: "Demasiados intentos. Prueba de nuevo en un rato." });
      }
      await recordIpAttempt(ipKey, 20, 60 * 60 * 1e3);
      const row = await getSurveyByToken(input.token);
      if (!row) throw new TRPCError3({ code: "NOT_FOUND", message: "Este link de la encuesta no es v\xE1lido." });
      const answer = parseSurveyAnswer(input);
      if (!answer) throw new TRPCError3({ code: "BAD_REQUEST", message: "Elige una nota de 1 a 5." });
      const saved = await saveSurveyResponse(input.token, answer);
      return { saved, alreadyAnswered: !saved };
    })
  }),
