    // "Deshacer" de la pantalla de éxito del terminal de gastos: borra sin
    // pedir la clave (a diferencia de `delete`) pero SOLO el gasto que esta
    // misma persona acaba de crear, dentro de 2 minutos. Pasado eso, o si lo
    // creó otro, hay que borrarlo con clave desde la lista.
    undoCreate: adminProcedure2.input(z8.object({ id: z8.number() })).mutation(async ({ input, ctx }) => {
      const expense = await getExpenseById(input.id);
      if (!expense) throw new TRPCError3({ code: "NOT_FOUND", message: "Ese gasto ya no existe." });
      const createdAt = new Date(expense.createdAt).getTime();
      const fresh = Date.now() - createdAt <= UNDO_EXPENSE_WINDOW_MS;
      if (expense.createdByUserId !== ctx.user.id || !fresh) {
        throw new TRPCError3({ code: "FORBIDDEN", message: "Ya no se puede deshacer: b\xF3rralo desde la lista con tu clave." });
      }
      await deleteExpense(input.id);
      await recordAdminAudit({ action: "expenses.undo", targetType: "expense", targetId: input.id, ip: clientIp(ctx) });
      return { success: true };
    }),
